interface Spec {
  alias: string;
  source: string;
  title: string;
  digest: string;
  /** first_seen_at hh:mm (Manila) on `digest`. */
  seen: [number, number];
  /** published_at; null or a ready timestamp. */
  published: string | null;
  status: ScoringStatus;
  score: number | null;
  tags: NewsTag[];
  attempts: number;
  why?: string;
  long?: boolean;
}

function build(s: Spec): FixtureNewsItem {
  const path = s.long ? `${s.alias}/${"a-very-long-path-segment-".repeat(6)}end` : s.alias;
  const url = `https://fixtures.example/news/${path}`;
  const scored = s.status === "scored";
  return {
    alias: s.alias,
    source_slug: s.source,
    guid: `fx-guid-${s.alias}`,
    canonical_url: url,
    url,
    title: s.title,
    author: s.alias.endsWith("3") ? null : "Fixture Author",
    published_at: s.published,
    first_seen_at: at(s.digest, s.seen[0], s.seen[1]),
    digest_date: s.digest,
    excerpt: `Excerpt for ${s.alias}.`,
    score: s.score,
    tags: s.tags,
    why_it_matters: scored ? (s.why ?? `Why ${s.alias} matters to First Mate engineers.`) : null,
    scoring_status: s.status,
    attempts: s.attempts,
    scored_at: scored ? at(s.digest, s.seen[0], s.seen[1] + 5) : null,
    scorer_model: scored ? "fixture-model" : null,
  };
}

