/** The 30 base items, in alias order. */
export const NEWS_ITEMS: FixtureNewsItem[] = specs.map(build);

function lowbarItems(): FixtureNewsItem[] {
  return [59, 50, 40, 20, 0].map((score, i) =>
    build({
      alias: `l0${i + 1}`,
      source: "fx-openai",
      title: `Fixture low-bar item ${i + 1}`,
      digest: D0,
      seen: [8, 1 + i],
      published: at(D0, 6, 1 + i),
      status: "scored",
      score,
      tags: score > 30 ? ["tooling"] : [],
      attempts: 1,
    }),
  );
}

function archiveItems(): FixtureNewsItem[] {
  return Array.from({ length: 60 }, (_, i) => {
    const day = 1 + (i % 27);
    const date = `2026-09-${String(day).padStart(2, "0")}`;
    const n = String(i + 1).padStart(2, "0");
    return build({
      alias: `a${n}`,
      source: ["fx-openai", "fx-hn", "fx-simon"][i % 3] ?? "fx-openai",
      title: `Fixture archive item ${n}`,
      digest: date,
      seen: [8, i % 50],
      published: at(date, 6, i % 50),
      status: "scored",
      score: (i * 7) % 101,
      tags: [(["new-model", "tooling", "framework", "security", "business"] as const)[i % 5] ?? "tooling"],
      attempts: 1,
    });
  });
}

export interface VariantData {
  /** Load the curriculum (levels, lessons, exercises) from tests/fixtures/content/content-valid. */
  content: boolean;
  sources: FixtureSource[];
  news: FixtureNewsItem[];
  runs: FixtureRun[];
}

export const VARIANTS: Record<string, () => VariantData> = {
  "fx-base": () => ({ content: true, sources: FIXTURE_SOURCES, news: NEWS_ITEMS, runs: FIXTURE_RUNS }),
  "fx-no-content": () => ({ content: false, sources: [], news: [], runs: [] }),
  "fx-no-news": () => ({ content: true, sources: FIXTURE_SOURCES, news: [], runs: [] }),
  "fx-news-lowbar": () => ({
    content: true,
    sources: FIXTURE_SOURCES,
    news: lowbarItems(),
    runs: [
      {
        alias: "run-lowbar",
        started_at: at(D0, 8, 0),
        finished_at: at(D0, 8, 3),
        trigger: "schedule",
        status: "success",
        fetched: 5,
        new: 5,
        scored: 5,
        pending: 0,
        failed: 0,
        skipped: 0,
        error_summary: null,
      },
    ],
  }),
  "fx-news-archive-60": () => ({
    content: true,
    sources: FIXTURE_SOURCES,
    news: [...archiveItems(), ...NEWS_ITEMS],
    runs: FIXTURE_RUNS,
  }),
};

export function buildVariant(name: string): VariantData {
  const make = VARIANTS[name];
  if (!make) throw new Error(`unknown variant '${name}' (valid: ${Object.keys(VARIANTS).join(", ")})`);
  return make();
}

/** alias (n01, l03, a12) -> canonical_url, so tests can find rows without hard-coded uuids. */
export function newsAliasToCanonicalUrl(alias: string): string {
  const item = [...NEWS_ITEMS, ...lowbarItems(), ...archiveItems()].find((i) => i.alias === alias);
  if (!item) throw new Error(`unknown news fixture alias '${alias}'`);
  return item.canonical_url;
}
